SET @c=(SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='conversations' AND COLUMN_NAME='lead_outcome');SET @s=IF(@c=0,'ALTER TABLE conversations ADD COLUMN lead_outcome VARCHAR(32) NULL AFTER lead_stage_key','DO 0');PREPARE x FROM @s;EXECUTE x;DEALLOCATE PREPARE x;
SET @c=(SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='conversations' AND COLUMN_NAME='lead_close_reason');SET @s=IF(@c=0,'ALTER TABLE conversations ADD COLUMN lead_close_reason VARCHAR(64) NULL AFTER lead_outcome','DO 0');PREPARE x FROM @s;EXECUTE x;DEALLOCATE PREPARE x;
SET @c=(SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='conversations' AND COLUMN_NAME='lead_outcome_note');SET @s=IF(@c=0,'ALTER TABLE conversations ADD COLUMN lead_outcome_note VARCHAR(500) NULL AFTER lead_close_reason','DO 0');PREPARE x FROM @s;EXECUTE x;DEALLOCATE PREPARE x;
SET @c=(SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='conversations' AND COLUMN_NAME='lead_outcome_updated_at');SET @s=IF(@c=0,'ALTER TABLE conversations ADD COLUMN lead_outcome_updated_at DATETIME NULL AFTER lead_outcome_note','DO 0');PREPARE x FROM @s;EXECUTE x;DEALLOCATE PREPARE x;
SET @c=(SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='conversations' AND COLUMN_NAME='lead_outcome_manager_id');SET @s=IF(@c=0,'ALTER TABLE conversations ADD COLUMN lead_outcome_manager_id BIGINT UNSIGNED NULL AFTER lead_outcome_updated_at','DO 0');PREPARE x FROM @s;EXECUTE x;DEALLOCATE PREPARE x;
SET @i=(SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='conversations' AND INDEX_NAME='idx_conversations_lead_outcome');SET @s=IF(@i=0,'ALTER TABLE conversations ADD KEY idx_conversations_lead_outcome (lead_outcome)','DO 0');PREPARE x FROM @s;EXECUTE x;DEALLOCATE PREPARE x;
